export const noteSlice = createSlice({
  name: '@@app/note',
  initialState,
  reducers: {
    addNote: (state, { payload }) => {
      const note = payload as NoteItem
      state.notes = [...state.notes, note]
    },
    deleteNote: (state, { payload }) => {
      const noteId = payload as string
      state.notes = state.notes.filter(note => note.id !== noteId)
    },
    updateNote: (state, { payload }) => {
      const note = payload as NoteItem
      state.notes = state.notes.map(item => (item.id === note.id ? note : item))
    },
    setNotes: (state, { payload }) => {
      const notes = payload as NoteItem[]
      state.notes = notes
    },
    trashNote: (state, { payload }) => {
      const noteId = payload as string
      state.notes = state.notes.map(note =>
        note.id === noteId ? { ...note, trash: true } : note
      )
    },
    restoreNote: (state, { payload }) => {
      const noteId = payload as string
      state.notes = state.notes.map(note =>
        note.id === noteId ? { ...note, trash: false } : note
      )
    },
    emptyTrash: state => {
      state.notes = state.notes.filter(note => !note.trash)
    },
